import{_ as o,o as n,c as a,a2 as e}from"./chunks/framework.CBVBgcDP.js";const p=JSON.parse('{"title":"ReAct: Synergizing Reasoning and Acting in Language Models","description":"","frontmatter":{"title":"ReAct: Synergizing Reasoning and Acting in Language Models","authors":"Shunyu Yao(姚顺雨), Jeffrey Zhao, Dian Yu, Nan Du, Izhak Shafran, Karthik Narasimhan, Yuan Cao(Princeton + Google Brain)","source":"ICLR 2023 · arXiv:2210.03629","status":"读完","date":"2026-07-28","link":"https://arxiv.org/abs/2210.03629","tags":["LLM","Agent","Reasoning","Prompting","CoT"]},"headers":[],"relativePath":"ai/agent/yao-2023-react.md","filePath":"ai/agent/yao-2023-react.md","lastUpdated":1786875695000}'),r={name:"ai/agent/yao-2023-react.md"};function s(i,t,g,l,d,c){return n(),a("div",null,[...t[0]||(t[0]=[e(`<h1 id="react-synergizing-reasoning-and-acting-in-language-models" tabindex="-1">ReAct: Synergizing Reasoning and Acting in Language Models <a class="header-anchor" href="#react-synergizing-reasoning-and-acting-in-language-models" aria-label="Permalink to &quot;ReAct: Synergizing Reasoning and Acting in Language Models&quot;">​</a></h1><blockquote><p><strong>一句话总结</strong>:把大模型的&quot;推理(想)&quot;和&quot;行动(调工具)&quot;交织进同一个循环——想一步→查一步→再想,让推理有真实事实兜底、行动有计划指引。它是今天几乎所有 AI Agent 的思想原型。 🔗 <strong>相关实操</strong>:Stage 1:手写 ReAct Loop · Stage 0:手写 Function Calling · 名词见<a href="/blog/ai/llm-basics/llm-dictionary.html">大模型基础名词词典</a></p></blockquote><h2 id="背景与动机" tabindex="-1">背景与动机 <a class="header-anchor" href="#背景与动机" aria-label="Permalink to &quot;背景与动机&quot;">​</a></h2><ul><li>在此之前,LLM 的两种能力被<strong>分开研究</strong>: <ul><li><strong>Reasoning 推理</strong>(如 Chain-of-Thought):只在&quot;脑子里&quot;空想,不接触外部世界 → 一旦某事实记错,后续全盘皆错(<strong>幻觉 + 错误传播</strong>)。</li><li><strong>Acting 行动</strong>(如动作计划生成):闷头做,不会边做边想、不会处理意外。</li></ul></li><li>核心洞察:<strong>人类做事时&quot;想&quot;和&quot;做&quot;本就是交织的</strong>——查资料时会想该搜什么→搜→看结果→纠偏再搜。ReAct 就是把这个循环搬给大模型。</li></ul><h2 id="核心方法-主要观点" tabindex="-1">核心方法 / 主要观点 <a class="header-anchor" href="#核心方法-主要观点" aria-label="Permalink to &quot;核心方法 / 主要观点&quot;">​</a></h2><p><strong>Thought → Action → Observation 交替循环</strong>(全文灵魂):</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>Thought:  我需要知道 X,应该先查 Y          ← 推理(内部,不与外界交互)</span></span>
<span class="line"><span>Action:   search[Y]                        ← 行动(调外部工具/API)</span></span>
<span class="line"><span>Observation: (Y 的搜索结果返回)            ← 环境反馈(外部真实事实)</span></span>
<span class="line"><span>Thought:  结果提到 Z 但没说 X,再查 Z</span></span>
<span class="line"><span>Action:   search[Z]</span></span>
<span class="line"><span>Observation: ...</span></span>
<span class="line"><span>Thought:  够了</span></span>
<span class="line"><span>Action:   finish[W]                         ← 结束</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><ul><li><strong>Thought</strong>:组织思路、拆计划、纠偏,不与外界交互 → 让推理&quot;引导&quot;行动。</li><li><strong>Action</strong>:真正调用外部。HotpotQA 里动作空间极简,仅三个:<code>search[实体]</code>、<code>lookup[关键词]</code>、<code>finish[答案]</code>。</li><li><strong>Observation</strong>:环境返回的真实反馈,把模型拉回现实 → 让行动&quot;喂事实&quot;给推理,治幻觉。</li><li>两者<strong>相互补台</strong>,即标题的 <strong>Synergizing(协同)</strong>。</li></ul><h3 id="真正的形式化贡献-把「想」定义成一个动作" tabindex="-1">真正的形式化贡献:把「想」定义成一个动作 <a class="header-anchor" href="#真正的形式化贡献-把「想」定义成一个动作" aria-label="Permalink to &quot;真正的形式化贡献:把「想」定义成一个动作&quot;">​</a></h3><p>论文一句话就把整件事讲完了:</p><blockquote><p><strong>Â = A ∪ L</strong>,其中 L 是语言空间。</p></blockquote><p>原本 agent 只有环境动作空间 <code>A</code>(点击、搜索、移动)。ReAct 干的事是把<strong>整个语言空间并进动作空间</strong>——「想一句话」从此是一个合法动作,只不过它<strong>不改变外部环境</strong>(论文原话:thought &quot;does not affect the external environment&quot;)。</p><p><strong>这才是 ReAct 的真正内核,而不是那个 Thought/Action/Observation 的模板。</strong> 两个推论:</p><ol><li><strong>动作空间从有限变成无限</strong>。<code>search</code> 只有几种写法,但「想什么」是开放的 → 这也是为什么它不能靠传统 RL 学(枚举不了),只能靠语言预训练的先验。</li><li><strong>今天的 reasoning 模型是同一件事的另一种实现</strong>。ReAct 靠 prompt 让模型在动作序列里插入语言;RLVR 把这个行为直接训进了权重。<strong>Thought 从「你要提示它」变成了「它默认就这么干」</strong>,但 <code>Â = A ∪ L</code> 这个结构没变。</li></ol><h2 id="关键结论" tabindex="-1">关键结论 <a class="header-anchor" href="#关键结论" aria-label="Permalink to &quot;关键结论&quot;">​</a></h2><h3 id="实验结果" tabindex="-1">实验结果 <a class="header-anchor" href="#实验结果" aria-label="Permalink to &quot;实验结果&quot;">​</a></h3><p><strong>知识密集任务(PaLM-540B,论文 Table 1)</strong>:</p><table tabindex="0"><thead><tr><th>方法</th><th>HotpotQA (EM)</th><th>Fever (Acc)</th></tr></thead><tbody><tr><td>Standard</td><td>28.7</td><td>57.1</td></tr><tr><td>CoT</td><td><strong>29.4</strong></td><td>56.3</td></tr><tr><td>CoT-SC(21 次自采样)</td><td>33.4</td><td>60.4</td></tr><tr><td>Act(只行动,无 Thought)</td><td>25.7</td><td>58.9</td></tr><tr><td><strong>ReAct</strong></td><td><strong>27.4</strong></td><td>60.9</td></tr><tr><td>ReAct → CoT-SC</td><td><strong>35.1</strong></td><td>62.0</td></tr><tr><td>CoT-SC → ReAct</td><td>34.2</td><td><strong>64.6</strong></td></tr></tbody></table><blockquote><p>⚠️ <strong>这张表最该被注意的一行,恰恰是通常被跳过的那行</strong>:在 HotpotQA 上,<strong>ReAct 单独用是输给 CoT 的(27.4 vs 29.4),甚至输给什么都不做的 Standard(28.7)</strong>。</p><p>所以「ReAct 比 CoT 强」是个流传很广但不准确的读法。论文真正证明的是:<strong>ReAct 和 CoT 各有各的病,只有把两者缝起来才同时超过两个单方(35.1 / 64.6)</strong>。下面「能查就查,查不到就靠想」不是一句漂亮的收尾,<strong>它是这篇论文唯一真正赢下 HotpotQA 的配置。</strong></p></blockquote><p><strong>交互式决策任务</strong>:</p><table tabindex="0"><thead><tr><th>数据集</th><th>ReAct</th><th>最强基线</th><th>差值</th></tr></thead><tbody><tr><td>ALFWorld(文字家务)</td><td><strong>71</strong>(best of 6);均值 57</td><td>BUTLER 37(best of 8)</td><td><strong>+34</strong></td></tr><tr><td>WebShop(网购)</td><td><strong>40.0</strong> 成功率 / 66.6 分</td><td>IL 29.1 / IL+RL 28.7</td><td><strong>+10.9</strong></td></tr></tbody></table><ul><li>最惊人处:<strong>仅 1~2 个 in-context 示例(不训练)</strong> 就打过需要大量训练的 IL / RL 方法。WebShop 的人类专家是 59.6,<strong>ReAct 的 40.0 离人还差得远</strong>——这是论文自己标出来的天花板。</li><li>⚠️ 那个 <strong>34% 是 best-of-6 对 best-of-8</strong>,ReAct 六次的<strong>均值只有 57</strong>(对应差值 +20)。摘要里的 34% 成立,但它是最好一次的成绩,不是期望成绩。</li></ul><h3 id="react-vs-cot-的本质差别" tabindex="-1">ReAct vs CoT 的本质差别 <a class="header-anchor" href="#react-vs-cot-的本质差别" aria-label="Permalink to &quot;ReAct vs CoT 的本质差别&quot;">​</a></h3><ul><li><p><strong>结构</strong>:CoT 和 ReAct 都会&quot;一步步推理&quot;,但 <strong>CoT 每步只能靠模型自己记住的知识(闭卷)</strong>,ReAct 每隔几步能去外部捞真实事实(<strong>开卷</strong>)。</p></li><li><p><strong>各自失败模式(论文的诚实之处)</strong>——论文人工标了 200 条轨迹(每种方法各 50 条对、50 条错),给出的是数字而不是形容词:</p><table tabindex="0"><thead><tr><th></th><th>CoT</th><th>ReAct</th></tr></thead><tbody><tr><td>答对且推理也对(true positive)</td><td>86%</td><td><strong>94%</strong></td></tr><tr><td>答对但推理是编的(false positive)</td><td>14%</td><td><strong>6%</strong></td></tr><tr><td><strong>幻觉</strong>在错误里的占比</td><td><strong>56%(最大失败源)</strong></td><td><strong>0%</strong></td></tr><tr><td>主要失败模式</td><td>幻觉</td><td>推理卡死 / 搜索捞不到有效信息</td></tr></tbody></table><p><strong>「幻觉 0%」和「HotpotQA 分数更低」同时成立</strong>,这两件事必须一起读:接地消灭了编造,但也把 agent 锁死在「搜到什么就只能用什么」上。ReAct 的病 = <strong>卡死/被检索绑架</strong>——搜索没用时会打转,或过度依赖搜到的信息、不敢用自身推理;更实事求是但更死板。</p></li><li><p><strong>最佳方案 = 两者结合</strong>,而且论文给的切换规则是具体可实现的(原「待深挖」的答案):</p><ul><li><strong>ReAct → CoT-SC</strong>:ReAct 在给定步数内答不出来就回退。步数上限 <strong>HotpotQA 7 步 / Fever 5 步</strong>。</li><li><strong>CoT-SC → ReAct</strong>:21 次自采样中<strong>多数答案出现次数 &lt; n/2</strong> 时(= 内部知识撑不住这道题)回退去查。采样温度 0.7。</li><li>两个方向都是同一句话:「<strong>能查就查,查不到就靠想</strong>」——而「该不该信自己」是用<strong>采样一致性</strong>当置信度来判的。这个「低一致性 → 去外部核对」的模式,今天仍然是最实用的一条 agent 启发式。</li></ul></li></ul><p><strong>经典例子(Figure 1)</strong>:问&quot;除了 Apple Remote,还有什么设备能控制它最初设计交互的程序?&quot;</p><ul><li>CoT 凭记忆瞎编答 <code>iPod</code>(错,幻觉,无纠错机制)。</li><li>ReAct:search[Apple Remote]→查到控制 Front Row→search[Front Row]→查到可由键盘功能键控制→<code>finish[keyboard function keys]</code>(对)。</li></ul><h3 id="被忽略的第三个实验-微调" tabindex="-1">被忽略的第三个实验:微调 <a class="header-anchor" href="#被忽略的第三个实验-微调" aria-label="Permalink to &quot;被忽略的第三个实验:微调&quot;">​</a></h3><p>论文末尾有一节几乎从不被引用,但它的含义比主实验更大——用 <strong>3,000 条自举出来的 ReAct 轨迹</strong>去微调小模型:</p><ul><li><strong>微调后的 PaLM-8B ReAct,打过所有 PaLM-62B 的 prompting 方法</strong></li><li><strong>微调后的 PaLM-62B ReAct,打过所有 540B 的 prompting 方法</strong></li><li>同样的微调数据量下,ReAct 轨迹显著优于用 Standard / CoT 轨迹微调</li></ul><p><strong>一句话:轨迹能换模型规模。</strong> 用 3,000 条好轨迹微调,顶得上把模型放大近一个数量级。</p><p>这条线后来长成了姚顺雨自己的 FireAct(500 条 GPT-4 轨迹微调 Llama2-7B),以及今天所有 agent 蒸馏的做法。它也解释了为什么他后来反复讲「<strong>数据/轨迹优先于架构</strong>」——这个判断在 2022 年这篇论文的最后一节就已经有实验支撑了,只是当时没人看。</p><h2 id="⚠️-反面证据-react-的收益可能不来自「交织推理」" tabindex="-1">⚠️ 反面证据:ReAct 的收益可能不来自「交织推理」 <a class="header-anchor" href="#⚠️-反面证据-react-的收益可能不来自「交织推理」" aria-label="Permalink to &quot;⚠️ 反面证据:ReAct 的收益可能不来自「交织推理」&quot;">​</a></h2><p>一篇笔记只记论文自己的说法是不够的。2024 年 Kambhampati 组的《On the Brittle Foundations of ReAct Prompting for Agentic Large Language Models》(arXiv:2405.13966)直接质疑了因果归因:</p><blockquote><p>性能&quot;受『把推理轨迹与动作执行交织』的影响极小&quot;(minimally influenced),LLM 表现出的推理能力&quot;源自<strong>示例与查询的相似度和近似检索</strong>,而非任何内在推理能力&quot;。</p></blockquote><p>也就是说:<strong>ReAct 有效 ≠ 因为它让模型「边想边做」,可能只是因为那 1~2 个 few-shot 示例和测试题长得像。</strong> 这和主实验里「ReAct 在 HotpotQA 上打不过 CoT」是相互印证的——如果交织推理本身有那么强,不该出现那个结果。</p><p><strong>怎么同时接受这两件事</strong>:ReAct 的<strong>理念</strong>(接地、可验证、把语言并进动作空间)被四年后的工程实践完整验证了;但它的<strong>机制解释</strong>(交织带来推理增益)是脆弱的、泛化性存疑的。<strong>范式活了下来,论文里的因果故事没有完全活下来。</strong></p><p>这也是读所有 agent 论文的通用姿势:<strong>分开看「这个结构该不该这么搭」和「作者对它为什么有效的解释」。</strong></p><h2 id="对我的启发-可迁移" tabindex="-1">对我的启发 / 可迁移 <a class="header-anchor" href="#对我的启发-可迁移" aria-label="Permalink to &quot;对我的启发 / 可迁移&quot;">​</a></h2><ul><li>它是今天几乎所有 <strong>AI Agent</strong> 的思想原型——工具调用型 Agent(包括能调工具的助手)底层循环就是 ReAct 的 Thought-Action-Observation。四年后的实际工程见 <a href="/blog/ai/agent/agent-loop.html">Agent:跟着一次循环走完全程</a>。</li><li>证明了 <strong>&quot;给模型外部工具 + 让它边想边用&quot; 比 &quot;把知识全塞进模型脑子&quot; 更可靠</strong>。</li><li><strong>可解释性</strong>:每步 Thought 都写出来,人能看懂它为什么这么做、错在哪 → 对信任与调试极重要。</li><li><strong>「置信度不足就去外部核对」是可以直接抄的工程模式</strong>:自采样一致性低 → 触发检索。不需要任何新模型能力。</li><li><strong>轨迹是比架构更便宜的杠杆</strong>(微调那节):要提升一个 agent,先想「我能不能攒 3,000 条好轨迹」,而不是先改 orchestration。</li><li>一句话记忆:<strong>CoT 让模型会想,ReAct 让模型边想边和世界核对。CoT 天花板是模型记住多少,ReAct 天花板是它能接触多少工具。</strong></li></ul><h2 id="时间线上的位置-为什么这篇重要" tabindex="-1">时间线上的位置(为什么这篇重要) <a class="header-anchor" href="#时间线上的位置-为什么这篇重要" aria-label="Permalink to &quot;时间线上的位置(为什么这篇重要)&quot;">​</a></h2><ul><li><p>姚顺雨说 ReAct 的原型早在 <strong>2021 年 11 月</strong>就有了,而 Chain-of-Thought(Wei et al.)是 <strong>2022 年 1 月</strong>才挂出来的——<strong>ReAct 的想法早于 CoT</strong>。他当时在做文字游戏,动机是一个朴素的问题:「为什么不让文字 agent 也思考?」(Latent Space 访谈)</p></li><li><p>论文投出时叫 ICLR 2023 Oral;它前面是 CALM(2020,他人生第一个 eureka:语言先验让「想」能泛化),后面是 Tree of Thoughts(2023,把思考做成树搜索)、SWE-bench(2023)、SWE-agent(2024,提出 ACI「agent 是一类新的终端用户」)。</p></li><li><p>三年后他在《The Second Half》(2025)里回头总结这条线,原话是:</p><blockquote><p>&quot;It turned out the most important part of RL might not even be the RL algorithm or environment, but <strong>the priors</strong>, which can be obtained in a way totally unrelated from RL.&quot;</p></blockquote><p>ReAct 就是这句话最早的实证:<strong>没训练,只靠语言预训练的先验 + 一个接地的循环,就打过了大量训练的 RL 基线。</strong></p></li></ul><h2 id="笔记与摘录" tabindex="-1">笔记与摘录 <a class="header-anchor" href="#笔记与摘录" aria-label="Permalink to &quot;笔记与摘录&quot;">​</a></h2><ul><li>摘要金句:&quot;reasoning traces help the model induce, track, and update action plans as well as handle exceptions, while actions allow it to interface with external sources ... to gather additional information.&quot;</li><li>形式化内核:<strong>Â = A ∪ L</strong>;thought &quot;does not affect the external environment&quot;。</li><li>还可深挖:ALFWorld 六次运行方差为什么这么大(均值 57 vs 最好 71)——这其实是今天「agent 可靠性 ≠ 能力」问题的最早征兆,姚顺雨后来在 τ-bench 里用 <strong>pass@1 vs pass^k</strong> 把它变成了正式度量(GPT-4o 零售 pass@1 约 61%,pass^8 跌到 25% 以下)。<strong>ReAct 这张表里的方差,四年后才有了名字。</strong></li></ul>`,43)])])}const u=o(r,[["render",s]]);export{p as __pageData,u as default};
